// Generates the icon-name lists from the material-symbols package (its index.d.ts lists every icon name) and the
// slot keys from src/app/core/icons/icon-slots.ts. Writes:
//   src/app/core/icons/icon-names.ts      (the frontend list the icon picker and app-icon use)
//   server/domain/tracker/icon-names.js   (the lists PUT /api/v1/tracker/settings validates iconOverrides against)
// Run from the repo root after a material-symbols upgrade or a new slot: node server/lib/gen-icon-names.mjs
// Commit both generated files.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..')
const source = path.join(root, 'node_modules', 'material-symbols', 'index.d.ts')
const slotsFile = path.join(root, 'src', 'app', 'core', 'icons', 'icon-slots.ts')

const names = [...new Set([...fs.readFileSync(source, 'utf8').matchAll(/^\s*"([a-z0-9_]+)",?\s*$/gm)].map((m) => m[1]))].sort()
if (names.length < 1000) throw new Error(`only ${names.length} icon names found in ${source}`)

const slots = [...fs.readFileSync(slotsFile, 'utf8').matchAll(/^\s*'([a-z][a-zA-Z0-9]*(?:\.[a-zA-Z0-9]+)+)':\s*\{/gm)].map((m) => m[1])
if (!slots.length) throw new Error(`no slot keys found in ${slotsFile}`)

// 12 names per line keeps the files short and the diffs readable.
const lines = []
for (let i = 0; i < names.length; i += 12) lines.push(names.slice(i, i + 12).join(' '))
const block = lines.join('\n')
const header = '// Generated by server/lib/gen-icon-names.mjs from the material-symbols package. Do not edit.\n'

fs.writeFileSync(
  path.join(root, 'src', 'app', 'core', 'icons', 'icon-names.ts'),
  `${header}const RAW = \`
${block}
\`

export const ICON_NAME_LIST: readonly string[] = RAW.trim().split(/\\s+/)

export const ICON_NAMES: ReadonlySet<string> = new Set(ICON_NAME_LIST)
`,
)

fs.writeFileSync(
  path.join(root, 'server', 'domain', 'tracker', 'icon-names.js'),
  `${header}const RAW = \`
${block}
\`

export const ICON_NAMES = new Set(RAW.trim().split(/\\s+/))

export const ICON_SLOT_KEYS = new Set(${JSON.stringify(slots).replaceAll('"', "'").replaceAll(',', ', ')})
`,
)

console.log(`wrote ${names.length} icon names and ${slots.length} slot keys`)
